import copy

_ITEM_FIELDS = {"sku", "label", "price_cents"}


def _validate_item(item):
    if not isinstance(item, dict):
        raise TypeError("item must be a dictionary")
    if set(item) != _ITEM_FIELDS:
        raise ValueError("item fields are invalid")
    if not isinstance(item["sku"], str) or not isinstance(item["label"], str):
        raise TypeError("sku and label must be strings")
    if not item["sku"] or not item["label"]:
        raise ValueError("sku and label must not be empty")
    price = item["price_cents"]
    if isinstance(price, bool) or not isinstance(price, int):
        raise TypeError("price_cents must be an integer")
    if price < 0:
        raise ValueError("price_cents must not be negative")


def apply_catalog_commands(catalog, commands):
    if not isinstance(catalog, dict):
        raise TypeError("catalog must be a dictionary")
    if not isinstance(commands, list):
        raise TypeError("commands must be a list")

    for category, items in catalog.items():
        if not isinstance(category, str):
            raise TypeError("category names must be strings")
        if not category:
            raise ValueError("category names must not be empty")
        if not isinstance(items, list):
            raise TypeError("category values must be lists")
        seen = set()
        for item in items:
            _validate_item(item)
            if item["sku"] in seen:
                raise ValueError("duplicate sku")
            seen.add(item["sku"])

    result = copy.deepcopy(catalog)
    for command in commands:
        if not isinstance(command, dict):
            raise TypeError("commands must be dictionaries")
        op = command.get("op")
        if op == "add":
            if set(command) != {"op", "category", "item"}:
                raise ValueError("invalid add command")
        elif op == "remove":
            if set(command) != {"op", "category", "sku"}:
                raise ValueError("invalid remove command")
        else:
            raise ValueError("unknown operation")

        category = command["category"]
        if not isinstance(category, str):
            raise TypeError("command category must be a string")
        if category not in result:
            raise ValueError("unknown category")

        if op == "add":
            _validate_item(command["item"])
            if any(item["sku"] == command["item"]["sku"] for item in result[category]):
                raise ValueError("duplicate sku")
            result[category].append(copy.deepcopy(command["item"]))
        else:
            sku = command["sku"]
            if not isinstance(sku, str):
                raise TypeError("sku must be a string")
            if not sku:
                raise ValueError("sku must not be empty")
            matches = [i for i, item in enumerate(result[category]) if item["sku"] == sku]
            if not matches:
                continue
            del result[category][matches[0]]
    return result

